(async()=>{
  const E=__echoes;
  const raf=()=>new Promise(r=>requestAnimationFrame(r));
  E.cmd('giveSkill','warding_aura');
  E.cmd('grantNode','ascend');
  E.cmd('openSocket');
  await raf(); await raf();
  document.querySelector('.nd-card').dispatchEvent(new MouseEvent('click',{bubbles:true}));
  await raf(); await raf();
  const cell=document.querySelectorAll('.nd-row')[0].querySelectorAll('.nd-cell')[0];
  cell.id='qa-watch';
  const rest=cell.getBoundingClientRect().x;
  cell.dispatchEvent(new MouseEvent('click',{bubbles:true}));
  const rows=[];
  const t0=performance.now();
  for(let i=0;i<70;i++){
    await raf();
    const live=document.querySelectorAll('.nd-row')[0].querySelectorAll('.nd-cell')[0];
    rows.push({t:Math.round(performance.now()-t0),same:live===cell,id:live.id||'-',dx:Math.round((live.getBoundingClientRect().x-rest)*100)/100,tr:getComputedStyle(live).transform,anim:getComputedStyle(live).animationName,cls:live.className});
  }
  const compact=rows.map(r=>`${r.t}|${r.same?'S':'N'}|${r.dx}|${r.anim}|${r.cls.replace('nd-cell','').trim()}`);
  return JSON.stringify({rest,compact});
})()
